  it('compiles a static inputSchema once across ten execute calls', async () => {
    const registry = new ToolRegistry();
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    registry.register(
      {name: 'ping', description: 'Takes no input', inputSchema: {type: 'object', properties: {}}},
      async () => 'pong'
    );

    for (let call = 0; call < 10; call += 1) {
      await registry.execute('ping', {});
    }

